const fallbackSale={id:'V-0128',date:'20 jul 2026',dateISO:'2026-07-20',type:'reservation',typeLabel:'Reserva',channel:'WhatsApp',comments:'Separar ambas prendas para retiro por la tarde.',client:{name:'Ana Martínez',phone:'+505 8888 2200'},total:2050,discount:90,payment:'partial',paid:1000,shippingPaid:0,delivery:'none',products:[{name:'Vestido satinado',variant:'Coral · Talla S',price:1250,image:'../../assets/catalog/coral-satin-dress.png',purpose:'direct'},{name:'Blusa seda',variant:'Champán · Talla M',price:800,image:'../../assets/catalog/blouse-champagne.png',purpose:'direct'}]};
const requestedId=new URLSearchParams(location.search).get('id');
let storedSale=null;
try{storedSale=JSON.parse(sessionStorage.getItem('pw-sale-detail')||'null');
}catch(error){console.warn('No se pudo recuperar la venta seleccionada.',error);
}const sale=storedSale?.id===requestedId?storedSale:fallbackSale;
const catalog=[{id:'dress',sku:'VES-1042',name:'Vestido satinado',price:1250,image:'../../assets/catalog/coral-satin-dress.png',variants:[{color:'Coral',sizes:{S:4,M:2,L:1}}]},{id:'blouse',sku:'BLU-2081',name:'Blusa seda',price:800,image:'../../assets/catalog/blouse-champagne.png',variants:[{color:'Champán',sizes:{S:2,M:5,L:2}}]},{id:'skirt',sku:'FAL-3104',name:'Falda plisada',price:740,image:'../../assets/catalog/black-skirt.png',variants:[{color:'Negro',sizes:{S:3,M:4,L:1}}]},{id:'jeans',sku:'JEA-4018',name:'Jean recto',price:890,image:'../../assets/catalog/blue-jeans.png',variants:[{color:'Azul',sizes:{S:2,M:4,L:3}}]}];
const money=value=>`C$ ${Number(value||0).toLocaleString('es-NI',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const roundMoney=value=>Math.round((Number(value||0)+Number.EPSILON)*100)/100;
const escapeHTML=value=>String(value??'').replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[character]));
const isLocalSale=()=>['local','tienda física'].includes(String(sale.channel).toLowerCase());
const variantParts=variant=>{const parts=String(variant||'Sin variante').split(' · ');
return{color:parts[0]||'Sin color',size:String(parts[1]||'Única').replace(/^Talla\s+/i,'')}};
let nextUid=1;
let activeDiscountUid=null;
let toastTimer;
const items=sale.products.map((product,index)=>{const quantity=Number(product.quantity||1);
const variant=variantParts(product.variant);
const campaignDiscount=Number(product.campaignDiscount||0);
const manualDiscount=Number(product.manualDiscount||0);
const gross=Number(product.regularPrice??(Number(product.price||0)+campaignDiscount+manualDiscount));
const catalogProduct=catalog.find(entry=>entry.name===product.name);
return{uid:nextUid++,catalogId:catalogProduct?.id||`existing-${index}`,sku:catalogProduct?.sku||`REG-${String(index+1).padStart(4,'0')}`,name:product.name,image:product.image||catalogProduct?.image,color:variant.color,size:variant.size,quantity,unitPrice:roundMoney(gross/quantity),purpose:product.purpose||'direct',fixedDiscount:campaignDiscount,manualDiscount,discountSource:product.discountSource||'',campaignName:product.campaignName||'',includedInTotal:product.includedInTotal??product.purpose!=='selection',selectionStatus:product.selectionStatus,source:product};
});
const assignedSaleDiscount=items.filter(item=>item.purpose!=='selection'||item.includedInTotal).reduce((sum,item)=>sum+item.fixedDiscount+item.manualDiscount,0);
const legacySaleDiscount=roundMoney(Math.max(0,Number(sale.discount||0)-assignedSaleDiscount));
const correctionForm=document.querySelector('#correctionForm');
const correctionContext=document.querySelector('.correction-context');
correctionContext.removeAttribute('aria-labelledby');correctionContext.setAttribute('aria-label','Contexto de la venta');
const itemsContainer=document.querySelector('#itemsContainer');
const itemSearch=document.querySelector('#itemSearch');
const productDialog=document.querySelector('#productDialog');
const productForm=document.querySelector('#productForm');
const productSearch=document.querySelector('#productSearch');
const productOptions=document.querySelector('#productOptions');
const productSelect=document.querySelector('#productSelect');
const colorSelect=document.querySelector('#colorSelect');
const sizeSelect=document.querySelector('#sizeSelect');
const productPurpose=document.querySelector('#productPurpose');
const discountDialog=document.querySelector('#discountDialog');
const discountForm=document.querySelector('#discountForm');
const confirmDialog=document.querySelector('#confirmDialog');
const confirmForm=document.querySelector('#confirmForm');
const toast=document.querySelector('#correctionToast');
const lineSubtotal=item=>roundMoney(item.unitPrice*item.quantity);
const lineDiscount=item=>roundMoney(Math.min(lineSubtotal(item),item.fixedDiscount+item.manualDiscount));
const lineTotal=item=>roundMoney(Math.max(0,lineSubtotal(item)-lineDiscount(item)));
const isBillable=item=>item.purpose!=='selection'||item.includedInTotal;
const correctedSubtotal=()=>roundMoney(items.filter(isBillable).reduce((sum,item)=>sum+lineSubtotal(item),0)+legacySaleDiscount);
const correctedDiscount=()=>roundMoney(items.filter(isBillable).reduce((sum,item)=>sum+lineDiscount(item),0)+legacySaleDiscount);
const correctedTotal=()=>roundMoney(Math.max(0,correctedSubtotal()-correctedDiscount()));
const paidTotal=()=>roundMoney(sale.productPaid??sale.paid);
const refundDue=()=>Math.max(0,roundMoney(paidTotal()-correctedTotal()));
const productForCatalog=id=>catalog.find(product=>product.id===id);
function showToast(message){clearTimeout(toastTimer);
toast.textContent=message;
toast.hidden=false;
toastTimer=setTimeout(()=>{toast.hidden=true;
},3000);
}function renderItems(){const term=itemSearch.value.trim().toLocaleLowerCase('es');
const visible=items.filter(item=>`${item.name} ${item.sku} ${item.color} ${item.size}`.toLocaleLowerCase('es').includes(term));
if(!items.length){itemsContainer.innerHTML='<div class="items-empty"><strong>La venta no tiene prendas</strong><p>Agrega al menos una prenda antes de guardar la corrección.</p><button id="emptyAddProduct" type="button">Agregar prenda</button></div>';
document.querySelector('#emptyAddProduct').addEventListener('click',openProductDialog);
}else if(!visible.length){itemsContainer.innerHTML='<div class="items-empty"><strong>No encontramos coincidencias</strong><p>Prueba con otro nombre, código o variante.</p></div>';
}else{itemsContainer.innerHTML=visible.map(item=>{const selection=item.purpose==='selection'&&!item.includedInTotal;
const discountLabel=item.manualDiscount?`Manual: −${money(item.manualDiscount)}`:'Descuento manual';
const campaign=item.fixedDiscount?`<em class="campaign-tag">Campaña${item.campaignName?` · ${escapeHTML(item.campaignName)}`:''}</em>`:'';
return`<article class="sale-item ${selection?'is-selection-item':''}" data-uid="${item.uid}"><img class="item-image" src="${item.image}" alt=""><div class="item-main"><strong>${escapeHTML(item.name)}</strong><small>SKU: ${escapeHTML(item.sku)}</small>${campaign}</div><div class="item-meta item-color"><small>Color</small><strong>${escapeHTML(item.color)}</strong></div><div class="item-meta item-size"><small>Talla</small><strong>${escapeHTML(item.size)}</strong></div><div class="item-quantity"><span class="sr-only">Cantidad de ${escapeHTML(item.name)}</span><div class="quantity-stepper"><button type="button" data-action="decrease" aria-label="Reducir cantidad">−</button><output aria-label="Cantidad">${item.quantity}</output><button type="button" data-action="increase" aria-label="Aumentar cantidad">＋</button></div></div><div class="item-purpose"><label class="sr-only" for="purpose-${item.uid}">Propósito de ${escapeHTML(item.name)}</label><select class="purpose-select" id="purpose-${item.uid}" data-action="purpose"><option value="direct" ${item.purpose==='direct'?'selected':''}>Venta directa</option><option value="selection" ${item.purpose==='selection'?'selected':''} ${isLocalSale()?'disabled':''}>Selección</option></select></div><button class="discount-button item-discount" type="button" data-action="discount">${discountLabel}</button><strong class="item-total">${selection?'<span class="selection-price-label">Sin cobrar</span>':money(lineTotal(item))}</strong><button class="remove-item" type="button" data-action="remove" aria-label="Quitar ${escapeHTML(item.name)}">⌫</button></article>`;
}).join('');
}document.querySelector('#itemsError').textContent='';
renderSummary();
}function renderSummary(){const total=correctedTotal();
const difference=roundMoney(total-Number(sale.total||0));
const balance=Math.max(0,roundMoney(total-paidTotal()));
document.querySelector('#originalTotal').textContent=money(sale.total);
document.querySelector('#correctedSubtotal').textContent=money(correctedSubtotal());
document.querySelector('#correctedDiscount').textContent=`− ${money(correctedDiscount())}`;
document.querySelector('#correctedTotal').textContent=money(total);
document.querySelector('#paidTotal').textContent=money(paidTotal());
document.querySelector('#balanceTotal').textContent=money(balance);
const refund=refundDue();
const refundRow=document.querySelector('#refundDueRow');
refundRow.hidden=refund===0;
document.querySelector('#refundDueTotal').textContent=money(refund);
const impact=document.querySelector('#correctionImpact');
impact.classList.toggle('is-increase',difference>0);
impact.classList.toggle('is-decrease',difference<0);
document.querySelector('#differenceTotal').textContent=difference===0?money(0):`${difference>0?'+':'−'} ${money(Math.abs(difference))}`;
document.querySelector('#differenceHelp').textContent=refund?`El nuevo total quedó por debajo de lo pagado. Debes reembolsar ${money(refund)}.`:difference>0?`El total aumenta y quedarán ${money(balance)} pendientes.`:difference<0?'El total de la venta disminuye.':'Sin cambios financieros.';
}function findItem(uid){return items.find(item=>item.uid===Number(uid));
}itemsContainer.addEventListener('click',event=>{const row=event.target.closest('.sale-item');
if(!row)return;
const item=findItem(row.dataset.uid);
const action=event.target.closest('[data-action]')?.dataset.action;
if(action==='increase'&&item.quantity<10)item.quantity+=1;
if(action==='decrease'&&item.quantity>1)item.quantity-=1;
if(action==='remove'){const index=items.indexOf(item);
items.splice(index,1);
showToast(`${item.name} se quitó de la corrección.`);
}if(action==='discount'){openDiscount(item);
return;
}renderItems();
});
itemsContainer.addEventListener('change',event=>{if(event.target.dataset.action!=='purpose')return;
const item=findItem(event.target.closest('.sale-item').dataset.uid);
item.purpose=isLocalSale()?'direct':event.target.value;
if(item.purpose==='selection'){item.includedInTotal=false;
item.selectionStatus='pending';
}else{item.includedInTotal=true;
item.selectionStatus=undefined;
}renderItems();
});
itemSearch.addEventListener('input',renderItems);
const productOptionValue=product=>`${product.sku} · ${product.name}`;
function findProduct(term){const value=term.trim().toLowerCase();
if(!value)return null;
const exact=catalog.find(product=>[product.id,product.sku,product.name,productOptionValue(product)].some(candidate=>candidate.toLowerCase()===value));
if(exact)return exact;
const matches=catalog.filter(product=>`${product.sku} ${product.name}`.toLowerCase().includes(value));
return matches.length===1?matches[0]:null;
}function clearProductSelection(){productSelect.value='';
colorSelect.innerHTML='';
sizeSelect.innerHTML='';
colorSelect.disabled=true;
sizeSelect.disabled=true;
document.querySelector('#stockHelp').textContent='Selecciona una prenda para consultar sus variantes y existencias.';
}function selectProduct(product){productSelect.value=product.id;
colorSelect.disabled=false;
sizeSelect.disabled=false;
colorSelect.innerHTML=product.variants.map(variant=>`<option>${variant.color}</option>`).join('');
updateSizeOptions();
document.querySelector('#productError').textContent='';
}function updateSizeOptions(){const product=productForCatalog(productSelect.value);
if(!product)return;
const variant=product.variants.find(entry=>entry.color===colorSelect.value);
sizeSelect.innerHTML=Object.entries(variant.sizes).map(([size,stock])=>`<option value="${size}" ${stock===0?'disabled':''}>${size} · ${stock} disponibles</option>`).join('');
const stock=variant.sizes[sizeSelect.value]??0;
document.querySelector('#stockHelp').textContent=`${product.sku} · ${money(product.price)} · Stock disponible: ${stock}.`;
}function openProductDialog(){productForm.reset();
productSearch.value='';
clearProductSelection();
productPurpose.querySelector('option[value="selection"]').disabled=isLocalSale();
if(isLocalSale())productPurpose.value='direct';
document.querySelector('#productError').textContent='';
productDialog.showModal();
productSearch.focus();
}productOptions.innerHTML=catalog.map(product=>`<option value="${productOptionValue(product)}"></option>`).join('');
productSearch.addEventListener('input',()=>{const product=findProduct(productSearch.value);
if(product)selectProduct(product);
else clearProductSelection();
});
productSearch.addEventListener('change',()=>{const product=findProduct(productSearch.value);
if(product){productSearch.value=productOptionValue(product);
selectProduct(product);
}});
colorSelect.addEventListener('change',updateSizeOptions);
sizeSelect.addEventListener('change',updateSizeOptions);
document.querySelector('#openProductDialog').addEventListener('click',openProductDialog);
document.querySelector('#addAnotherProduct').addEventListener('click',openProductDialog);
productForm.addEventListener('submit',event=>{if(event.submitter?.value!=='add')return;
event.preventDefault();
const data=new FormData(productForm);
const product=productForCatalog(data.get('product'));
if(!product){document.querySelector('#productError').textContent='Busca y selecciona una prenda por su código o nombre.';
productSearch.focus();
return;
}const variant=product.variants.find(entry=>entry.color===data.get('color'));
const quantity=Number(data.get('quantity'));
const available=variant.sizes[data.get('size')];
if(!Number.isInteger(quantity)||quantity<1||quantity>available){document.querySelector('#productError').textContent=`La cantidad debe estar entre 1 y ${available}.`;
return;
}const purpose=isLocalSale()?'direct':data.get('purpose');
const duplicate=items.find(item=>item.catalogId===product.id&&item.color===data.get('color')&&item.size===data.get('size')&&item.purpose===purpose);
if(duplicate){if(duplicate.quantity+quantity>available){document.querySelector('#productError').textContent=`Solo hay ${available} unidades disponibles para esta variante.`;
return;
}duplicate.quantity+=quantity;
}else{items.push({uid:nextUid++,catalogId:product.id,sku:product.sku,name:product.name,image:product.image,color:data.get('color'),size:data.get('size'),quantity,unitPrice:product.price,purpose,fixedDiscount:0,manualDiscount:0,discountSource:'',campaignName:'',includedInTotal:purpose==='direct',selectionStatus:purpose==='selection'?'pending':undefined,source:{}});
}productDialog.close('added');
itemSearch.value='';
renderItems();
showToast(`${product.name} se agregó a la corrección.`);
});
function openDiscount(item){activeDiscountUid=item.uid;
document.querySelector('#discountProduct').textContent=`${item.name} · ${item.color} · Talla ${item.size} · Base disponible ${money(Math.max(0,lineSubtotal(item)-item.fixedDiscount))}`;
discountForm.reset();
if(item.manualDiscount){discountForm.elements.discountType.value='amount';
document.querySelector('#discountValue').value=item.manualDiscount;
}document.querySelector('#discountError').textContent='';
discountDialog.showModal();
document.querySelector('#discountValue').focus();
}discountForm.addEventListener('submit',event=>{if(event.submitter?.value!=='apply')return;
event.preventDefault();
const item=findItem(activeDiscountUid);
const data=new FormData(discountForm);
const value=Number(data.get('discountValue'));
const base=Math.max(0,roundMoney(lineSubtotal(item)-item.fixedDiscount));
let amount=0;
if(data.get('discountType')==='percent')amount=base*(value/100);
if(data.get('discountType')==='amount')amount=value;
if(data.get('discountType')==='final')amount=base-value;
if(!Number.isFinite(amount)||amount<0||amount>base){document.querySelector('#discountError').textContent=`El descuento debe dejar un precio entre ${money(0)} y ${money(base)}.`;
return;
}item.manualDiscount=roundMoney(amount);
item.discountSource=data.get('discountSource');
discountDialog.close('applied');
renderItems();
showToast(item.manualDiscount?'Descuento aplicado a la prenda.':'Descuento manual retirado.');
});
correctionForm.addEventListener('submit',event=>{event.preventDefault();
let valid=true;
if(!items.length){document.querySelector('#itemsError').textContent='Agrega al menos una prenda para guardar la corrección.';
valid=false;
}if(!valid){document.querySelector('.form-error:not(:empty)')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});
return;
}const difference=roundMoney(correctedTotal()-Number(sale.total||0));
const balance=Math.max(0,roundMoney(correctedTotal()-paidTotal()));
const refund=refundDue();
document.querySelector('#confirmOriginal').textContent=money(sale.total);
document.querySelector('#confirmCorrected').textContent=money(correctedTotal());
const confirmRefund=document.querySelector('#confirmRefund');
confirmRefund.hidden=refund===0;
document.querySelector('#confirmRefundTotal').textContent=money(refund);
document.querySelector('#confirmImpactTitle').textContent=refund?`Se deben reembolsar ${money(refund)}`:difference>0?`El total aumenta ${money(difference)}`:difference<0?`El total disminuye ${money(Math.abs(difference))}`:'El total no cambia';
document.querySelector('#confirmImpactHelp').textContent=refund?'Lo pagado supera el nuevo total. Registra el reembolso por separado después de guardar.':difference>0?`Después de la corrección quedarán ${money(balance)} pendientes.`:difference<0?'La clienta tendrá un saldo menor por pagar.':'Los cambios de prendas no alteran el total de la venta.';
confirmDialog.showModal();
});
function persistSale(){sessionStorage.setItem('pw-sale-detail',JSON.stringify(sale));
try{const created=JSON.parse(localStorage.getItem('pw-created-sale')||'null');
if(created?.id===sale.id)localStorage.setItem('pw-created-sale',JSON.stringify(sale));
}catch(error){console.warn('No se pudo actualizar la venta guardada.',error);
}}confirmForm.addEventListener('submit',event=>{if(event.submitter?.value!=='confirm')return;
event.preventDefault();
const total=correctedTotal();
sale.products=items.map(item=>({...item.source,name:item.name,variant:`${item.color} · Talla ${item.size}`,quantity:item.quantity,price:lineTotal(item),regularPrice:lineSubtotal(item),campaignDiscount:item.fixedDiscount,manualDiscount:item.manualDiscount,discountSource:item.discountSource||undefined,image:item.image,purpose:item.purpose,includedInTotal:item.includedInTotal,selectionStatus:item.purpose==='selection'?(item.selectionStatus||'pending'):undefined}));
sale.total=total;
sale.discount=correctedDiscount();
sale.manualDiscount=roundMoney(items.reduce((sum,item)=>sum+item.manualDiscount,0));
sale.payment=paidTotal()>=sale.total?'paid':'partial';
sale.adminCorrections??=[];
sale.adminCorrections.push({label:'Prendas, propósito o descuentos corregidos',icon:'✎',at:'Hoy · ahora',by:'María Pérez'});
persistSale();
confirmDialog.close('confirmed');
location.href=`sale-detail.html?id=${encodeURIComponent(sale.id)}`;
});
document.querySelector('#saleReference').textContent=`#${sale.id} · ${sale.date}`;
document.querySelector('#saleClient').textContent=sale.client?.name||'Sin cliente asociado';
document.querySelector('#saleChannel').textContent=sale.channel;
document.querySelector('#channelRule').textContent=isLocalSale()?'La venta local solo admite prendas para venta directa.':'Permite venta directa y prendas en selección.';
document.querySelector('#summarySaleId').textContent=`Venta #${sale.id}`;
document.querySelector('#backToSale').href=`sale-detail.html?id=${encodeURIComponent(sale.id)}`;
const root=document.documentElement;
const themeButton=document.querySelector('.theme-button');
function setTheme(theme){root.dataset.theme=theme;
const dark=theme==='dark';
themeButton.setAttribute('aria-pressed',String(dark));
themeButton.setAttribute('aria-label',dark?'Activar modo claro':'Activar modo oscuro');
themeButton.querySelector('.theme-label').textContent=dark?'Modo claro':'Modo oscuro';
localStorage.setItem('pw-theme',theme);
}setTheme(localStorage.getItem('pw-theme')||'light');
themeButton.addEventListener('click',()=>setTheme(root.dataset.theme==='dark'?'light':'dark'));
const menuButton=document.querySelector('.menu-button');
const sidebar=document.querySelector('.sidebar');
const navBackdrop=document.querySelector('.nav-backdrop');
function closeMenu(){sidebar.classList.remove('is-open');
navBackdrop.hidden=true;
menuButton.setAttribute('aria-expanded','false');
}menuButton.setAttribute('aria-expanded','false');
menuButton.addEventListener('click',()=>{const opening=!sidebar.classList.contains('is-open');
sidebar.classList.toggle('is-open',opening);
navBackdrop.hidden=!opening;
menuButton.setAttribute('aria-expanded',String(opening));
});
navBackdrop.addEventListener('click',closeMenu);
renderItems();

